#include <bits/stdc++.h>
using namespace std;

int main() {
    int n; long long k;
    if (scanf("%d %lld", &n, &k) != 2) return 0;
    vector<long long> a(n);
    for (auto &x : a) scanf("%lld", &x);
    // Sliding window: all values are positive, so shrink from the left while the sum exceeds k.
    long long s = 0;
    int l = 0, best = 0;
    for (int r = 0; r < n; r++) {
        s += a[r];
        while (s > k) s -= a[l++];
        best = max(best, r - l + 1);
    }
    printf("%d\n", best);
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken(); int n = (int) st.nval;
        st.nextToken(); long k = (long) st.nval;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) { st.nextToken(); a[i] = (long) st.nval; }
        // Sliding window: all values are positive, so shrink from the left while the sum exceeds k.
        long s = 0;
        int l = 0, best = 0;
        for (int r = 0; r < n; r++) {
            s += a[r];
            while (s > k) s -= a[l++];
            best = Math.max(best, r - l + 1);
        }
        System.out.println(best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<16)
	var n int
	var k int64
	fmt.Fscan(in, &n, &k)
	a := make([]int64, n)
	for i := range a {
		fmt.Fscan(in, &a[i])
	}
	// Sliding window: all values are positive, so shrink from the left while the sum exceeds k.
	var s int64
	l, best := 0, 0
	for r := 0; r < n; r++ {
		s += a[r]
		for s > k {
			s -= a[l]
			l++
		}
		best = max(best, r-l+1)
	}
	fmt.Println(best)
}
